<?php
function renderProduct(array $p,array $site): void { ?>
<section class="product-page"><nav class="crumbs" aria-label="Breadcrumb"><a href="/products"><?=copyText($site,'product.allProducts')?></a><span>/</span><a href="/products?category=<?=e($p['category']['slug'])?>"><?=e($p['category']['name'])?></a></nav>
<div class="product-detail">
<div class="product-media"><div class="product-gallery <?=count($p['images'])>1?'has-thumbnails':''?>"><button class="photo-zoom plain" aria-label="Zoom product photo"><img id="main-photo" src="<?=e($p['images'][0]['url']??'/category-samples/hardware.webp')?>" alt="<?=e($p['name'])?>"></button><div class="thumbnails"><?php foreach($p['images'] as $i=>$im):?><button class="plain" data-photo="<?=e($im['url'])?>" aria-label="View photo <?=$i+1?>"><img src="<?=e($im['thumb'])?>" alt=""></button><?php endforeach;?></div></div><p class="photo-note">Product photos</p><div class="product-seller"><span>M</span><div><strong>MATTE Ltd</strong><p>Kigali, Rwanda</p><a href="/about">About our store</a></div></div></div>
<div class="product-info"><p class="eyebrow"><?=e($p['category']['name'])?></p><h1><?=e($p['name'])?></h1><p><?=e($p['summary'])?></p><p class="price"><?=$p['price']===null?copyText($site,'product.askPrice'):number_format($p['price']).' RWF'?> <small>/ <?=e($p['unit'])?></small></p><p class="product-stock <?=$p['inStock']?'available':'out'?>"><?=copyText($site,$p['inStock']?'product.inStock':'product.outOfStock')?><?=$p['inStock']?' / '.$p['stockQuantity']:''?></p><dl class="specs product-highlights"><?php foreach(array_slice((array)$p['specs'],0,4,true) as $k=>$v):?><dt><?=e($k)?></dt><dd><?=e($v)?></dd><?php endforeach;?></dl><div id="product-colors" data-slug="<?=e($p['slug'])?>"></div><a href="#product-details" class="detail-link">View full product details</a></div>
<aside class="product-order" aria-label="Order this product"><div class="product-shipping"><h2>Shipping</h2><p>Collect from MATTE without a delivery fee, or choose delivery. MATTE connects you with a transporter; you negotiate the delivery price, timing and arrangements directly with the transporter.</p></div><h2>Order from MATTE</h2><p class="order-price"><?=$p['price']===null?copyText($site,'product.askPrice'):number_format($p['price']).' RWF'?> <small>/ <?=e($p['unit'])?></small></p><?php if($p['orderable']):?><label>Quantity<input id="product-qty" type="number" min="1" max="<?=min(999,$p['stockQuantity'])?>" value="1"></label><button data-add="<?=$p['id']?>" data-quantity="product-qty"><?=copyText($site,'product.addToCart')?></button><?php endif;?><a class="button" href="/quote?productId=<?=$p['id']?>">Send inquiry</a><button class="secondary" data-ask="<?=$p['id']?>" data-name="<?=e($p['name'])?>">Chat now</button><p class="payment-note"><strong><?=copyText($site,'product.payTitle')?></strong> <?=copyText($site,'product.payBody')?></p><div class="product-service"><strong>Delivery or store pickup</strong><p>Choose your delivery address or collect from our store at checkout.</p></div></aside>
</div>
<nav class="product-section-nav" aria-label="Product sections"><a href="#product-details">Product details</a><a href="#product-specifications">Specifications</a><a href="#related-products">Related products</a></nav><div class="product-description"><section id="product-details"><p class="eyebrow">Product details</p><h2><?=copyText($site,'product.about')?></h2><p class="prewrap"><?=e($p['description'])?></p></section><section id="product-specifications"><p class="eyebrow">At a glance</p><h2><?=copyText($site,'product.specifications')?></h2><dl class="specs"><?php foreach((array)$p['specs'] as $k=>$v):?><dt><?=e($k)?></dt><dd><?=e($v)?></dd><?php endforeach;?></dl></section></div><section id="related-products"><h2><?=copyText($site,'product.moreIn')?> <?=e($p['category']['name'])?></h2><div id="related" class="product-grid"></div></section></section>
<?php }
